// UULA Toolkit — opens a tool from its own repository, live:
// fetches the newest app.html of the tool (e.g. https://zaheralkablawi.github.io/uula-math/app.html),
// adds the Toolkit parts (the "All tools" bar, one look, tooltips, logos) and shows it in this page.
// No connection → the copy saved with the Toolkit (bundle.html next to this tool's page).
// build.py fills var P = {"THEME": "/* UULA Toolkit — one look for every tool (added last, so it wins over each tool's own styles).\n   Sizes: body 14 · section title 14/600 · group label 12/600 muted · buttons 12.5 · notes 11.8 · status 12.8 · footer 11.5 */\n:root{--accent:#1f71de;--accent-soft:#e7effc}\nbutton,input,select,textarea{font-family:inherit}\n.credit,.ver{font-size:11.5px!important;color:#5d6878!important}\n.note{font-size:11.8px!important;color:#5d6878}\n.status{font-size:12.8px!important}\n.gt2,.splab.gt2{font-size:14px!important;font-weight:600!important;color:#18212e!important}\n.label,.tgroup .gt{font-size:12px!important;font-weight:600!important;color:#5d6878!important}\n/* segmented choices (scope, alignment, position, type) */\n.seg button{font-size:12.5px!important;height:26px!important;min-height:26px!important;padding:0 4px!important;line-height:1.2!important}\n.seg4 button{font-size:11.5px!important}\n.seg button[aria-pressed=\"true\"]{font-weight:600}\n/* tab bars */\n#tabs button,#wtabs button,.tabs button{font-size:11.5px!important}\n/* text fields */\n.tin{font-size:13px!important;height:30px!important}\n/* checkboxes, menus and settings rows */\n.chk{font-size:13px!important}\n/* every menu (☰ and Graph's menus): 12px */\n.menu button{font-size:12px!important}\n#mnu .mi,#mnu .mrow,.mi{font-size:12px!important}\n#setBody .row{font-size:13px}\n", "TOOL_CSS": {"dark": ".dbtn{height:30px!important;font-size:13.5px!important;border-radius:8px!important}.sbody b{font-size:13.5px}", "cover": "#tPos button,#iPos button{font-weight:600!important}", "math": "body{font-size:14px}h1{margin-right:0!important;position:relative;left:2px}", "graph": ":root{--bg:#f3f5f8;--line:#d9dfe7;--fg:#18212e;--muted:#5d6878;--accent:#1f71de}body>footer,#app>footer,footer{font-size:11.5px!important;color:#5d6878!important;text-align:center}.brand{position:relative;right:4px}", "restyle": ".ib.lang{color:#5d6878;font-weight:600;font-size:.8rem}header h1{margin-right:4px}"}, "SCRIPTS": "// UULA Toolkit — one icon set for every menu (same drawings as UULA Graph's menu: 24px grid, stroke 2)\nvar TK_ICONS = {\n  upd: '<path d=\"M20 11a8 8 0 0 0-14.9-3.5L4 9\"/><path d=\"M4 4v5h5\"/><path d=\"M4 13a8 8 0 0 0 14.9 3.5L20 15\"/><path d=\"M20 20v-5h-5\"/>',\n  lang: '<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M3 12h18M12 3c3 3.5 3 14.5 0 18M12 3c-3 3.5-3 14.5 0 18\"/>',\n  edit: '<path d=\"M4 20h4L19 9l-4-4L4 16z\"/><path d=\"M13.5 6.5l4 4\"/>',\n  tools: '<path d=\"M4 6h9M17 6h3M4 12h3M11 12h9M4 18h11M19 18h1\"/><circle cx=\"15\" cy=\"6\" r=\"2\"/><circle cx=\"9\" cy=\"12\" r=\"2\"/><circle cx=\"17\" cy=\"18\" r=\"2\"/>',\n  about: '<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 11v6M12 7.5h.01\"/>',\n  new: '<path d=\"M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z\"/><path d=\"M12 11v6M9 14h6\"/>',\n  help: '<path d=\"M4 5a2 2 0 0 1 2-2h12v16H6a2 2 0 0 0-2 2z\"/><path d=\"M8 7h7M8 11h5\"/>',\n  keys: '<rect x=\"2\" y=\"6\" width=\"20\" height=\"12\" rx=\"2\"/><path d=\"M6 10h.01M10 10h.01M14 10h.01M18 10h.01M8 14h8\"/>',\n  news: '<path d=\"M12 3l1.9 5.1L19 10l-5.1 1.9L12 17l-1.9-5.1L5 10l5.1-1.9z\"/><path d=\"M19 16l.7 1.8 1.8.7-1.8.7L19 21l-.7-1.8-1.8-.7 1.8-.7z\"/>'\n};\nvar TK_MENU_CSS =\n  '.tki{display:flex!important;align-items:center;gap:8px}' +\n  '.tki::before{content:\"\";flex:none;width:15px;height:15px;background:currentColor;' +\n  '-webkit-mask:var(--tki) center/contain no-repeat;mask:var(--tki) center/contain no-repeat}';\nfunction tkIcon(el, name) {\n  if (!el || !TK_ICONS[name]) return;\n  var svg = '<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"black\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">' + TK_ICONS[name] + '</svg>';\n  el.classList.add('tki');\n  el.style.setProperty('--tki', 'url(\"data:image/svg+xml,' + encodeURIComponent(svg) + '\")');\n}\n// UULA Toolkit — thin bar added on top of every tool: back to the tools list\nvar TK_MENU_LEFT = 10;\n(function () {\n  function add() {\n    if (document.getElementById('tkBar')) return;\n    var en = false;\n    try { en = localStorage.getItem('tk-lang') === 'en'; } catch (e) {}\n    var label = en ? 'All tools' : 'كل الأدوات';\n    var css = document.createElement('style');\n    css.textContent =\n      '#tkBar{position:sticky;top:0;z-index:1000;display:flex;align-items:center;gap:8px;height:30px;padding:0 10px;' +\n      'background:#fff;border-bottom:1px solid #d9dfe7;direction:rtl;font:13px \"UULA Sans\",-apple-system,\"Segoe UI\",Tahoma,sans-serif}' +\n      '#tkBar button{display:inline-flex;align-items:center;gap:5px;height:24px;padding:0 8px;border:1px solid #d9dfe7;border-radius:7px;' +\n      'background:#fff;color:#1f71de;font:inherit;font-size:12px;font-weight:600;cursor:pointer}' +\n      '#tkBar button:hover{border-color:#1f71de;background:#e7effc}' +\n      '#tkBar span{margin-inline-start:auto;color:#9aa3b0;font-size:11px;direction:ltr}';\n    document.head.appendChild(css);\n    var b = document.createElement('div');\n    b.id = 'tkBar';\n    b.innerHTML =\n      '<button type=\"button\" title=\"' + label + '\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 20 20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\">' +\n      '<path d=\"M8 4l6 6-6 6\"/></svg>' + label + '</button><span>UULA Toolkit</span>';\n    b.querySelector('button').addEventListener('click', function () {\n      location.href = '../../index.html?v=' + Date.now();\n    });\n    document.body.insertBefore(b, document.body.firstChild);\n    menuIcons(); pinGraphMenu();\n  }\n  function menuIcons() {\n    var css2 = document.createElement('style'); css2.textContent = TK_MENU_CSS; document.head.appendChild(css2);\n    var m = document.getElementById('appMenu'); if (!m) return;\n    var q = function (s) { return m.querySelector(s); };\n    var lb = document.getElementById('langBtn');\n    // a tool with a language button but no language item in its menu (Restyle): add the item, so the button can go\n    if (lb && !q('#langItem')) {\n      var li = document.createElement('button'); li.type = 'button'; li.id = 'langItem';\n      var label = function () { li.textContent = document.documentElement.lang === 'en' ? 'العربية' : 'English'; };\n      label();\n      li.addEventListener('click', function (e) {\n        e.stopPropagation(); m.hidden = true;\n        var mb = document.getElementById('menuBtn'); if (mb) mb.setAttribute('aria-expanded', 'false');\n        lb.click(); label();\n      });\n      m.insertBefore(li, q('#aboutBtn'));\n    }\n    if (lb && q('#langItem')) lb.style.display = 'none';\n    // keep the menu inside the pane in both languages (in English some tools open it towards the outside)\n    // every tool's menu opens at the same place: the left edge of the pane, in Arabic and English\n    var fit = function () {\n      if (m.hidden) return;\n      var d = document.documentElement.lang === 'en' ? 'ltr' : 'rtl'; if (m.dir !== d) m.dir = d;\n      var mb = document.getElementById('menuBtn'), top = mb ? mb.getBoundingClientRect().bottom + 4 : 40;\n      m.style.setProperty('position', 'fixed', 'important'); m.style.setProperty('left', TK_MENU_LEFT + 'px', 'important');\n      m.style.setProperty('right', 'auto', 'important'); m.style.setProperty('top', top + 'px', 'important');\n    };\n    new MutationObserver(fit).observe(m, { attributes: true, attributeFilter: ['hidden', 'dir'] });\n    tkIcon(q('#chkUpd'), 'upd'); tkIcon(q('#langItem'), 'lang'); tkIcon(q('#aboutBtn'), 'about');\n    ['new', 'help', 'keys', 'news', 'about', 'edit'].forEach(function (a) { tkIcon(q('[data-act=\"' + a + '\"]'), a); });\n  }\n  // UULA Graph opens its menus from the top bar (#mnu): keep them at the same left edge too\n  function pinGraphMenu() {\n    var g = document.getElementById('mnu'); if (!g) return;\n    new MutationObserver(function () { if (g.hidden) return;\n      if (g.style.left !== TK_MENU_LEFT + 'px') { g.style.left = TK_MENU_LEFT + 'px'; g.style.right = 'auto'; } })\n      .observe(g, { attributes: true, attributeFilter: ['hidden', 'style'] });\n  }\n  if (document.body) add(); else document.addEventListener('DOMContentLoaded', add);\n})();\n// UULA Toolkit — one tooltip for every button in every tool:\n// the button's name (bold), then how and why to use it. Arabic and English.\n// window.TK_TOOL tells which tool this page is (home, dark, cover, restyle, math, graph).\n(function () {\n  var TOOL = window.TK_TOOL || '';\n  function E(ar, en, nar, nen) { return { ar: ar, en: en || '', n: nar ? { ar: nar, en: nen || nar } : null }; }\n\n  // ---------- shared by every tool ----------\n  var COMMON = [\n    ['#tkBar button', E('يرجع إلى قائمة كل أدوات UULA Toolkit.', 'Goes back to the list of all UULA Toolkit tools.')],\n    ['#updBtn', E('يوجد إصدار جديد من الأداة. اضغط لتحميله.', 'A new version of the tool is ready. Click to load it.')],\n    ['#chkUpd', E('يفحص إن كان هناك إصدار أحدث من الأداة.', 'Checks whether a newer version of the tool is available.')],\n    ['#langItem', E('يبدّل لغة الأداة بين العربية والإنجليزية.', 'Switches the tool between Arabic and English.')],\n    ['#aboutBtn', E('معلومات عن الأداة وما تفعله.', 'What the tool does.')],\n    ['#modalX', E('يغلق هذه النافذة.', 'Closes this window.')]\n  ];\n\n  var RULES = {\n    home: [\n      ['#menuBtn', E('تحرير الأدوات، والتحقق من التحديثات، وتغيير اللغة.', 'Edit tools, check for updates and change the language.')],\n      ['#toolsItem', E('أظهر أو أخفِ الأدوات، واسحبها لترتيبها في القائمة.', 'Show or hide tools, and drag them to order the list.')],\n      ['.mrow .sw', E('يُظهر الأداة في القائمة أو يخفيها. الإخفاء لا يحذف الأداة.', 'Shows or hides the tool in the list. Hiding does not remove it.')],\n      ['.mrow', E('اسحب الأداة لأعلى أو لأسفل لتغيير مكانها في القائمة.', 'Drag the tool up or down to change its place in the list.')],\n      ['.tool', function (el) { return E('اضغط لفتح الأداة. وللرجوع إلى هذه القائمة اضغط «كل الأدوات» في أعلاها.', 'Click to open the tool. To come back here, click \"All tools\" at its top.', el.querySelector('b').textContent); }]\n    ],\n\n    // UULA Dark and UULA Cover share one page\n    dark: [\n      ['#menuBtn', E('التحقق من التحديثات، وتغيير اللغة، وحول الأداة.', 'Check for updates, change the language and about.')],\n      ['#suggestSep', E('تبحث الأداة عن أماكن مناسبة للتقسيم وتضع فواصل حمراء مقترحة. راجعها وحرّكها أو احذفها قبل التحويل.', 'The tool looks for good places to split and adds suggested red separators. Review, move or delete them before converting.', 'اقترح الفواصل', 'Suggest separators')],\n      ['#addSep', E('يضيف فاصلًا أحمر في الشريحة الحالية. اسحبه إلى المكان الذي تبدأ منه شريحة جديدة.', 'Adds a red separator to the current slide. Drag it to where a new slide should start.', 'أضف فاصلًا', 'Add separator')],\n      ['#makePart', E('حدّد العناصر التي تريدها في شريحة واحدة ثم اضغط. مفيد عندما لا يصلح التقسيم بخط أفقي.', 'Select the items that belong on one slide, then click. Useful when a straight line cannot split them.', 'جزء مستقل', 'Own part')],\n      ['#clearParts', E('يلغي الأجزاء المستقلة في الشرائح المحددة لتبدأ تقسيمها من جديد.', 'Removes the own parts in the selected slides so you can split them again.', 'إلغاء الأجزاء', 'Clear parts')],\n      ['label:has(#s1Done)', E('علّمها بعد الانتهاء من الفواصل. زر التحويل لا يعمل قبل إكمال الخطوتين.', 'Tick it once the separators are done. Convert works only after both steps.', 'تم تقسيم الشرائح', 'Slides split')],\n      ['label:has(#s2Done)', E('علّمها بعد تغيير مقاس الشرائح إلى 16:9 من تبويب تصميم ← حجم الشريحة.', 'Tick it after changing the slide size to 16:9 (Design ← Slide Size).', 'تم تحويل المقاس', 'Size changed')],\n      ['#scope [data-v=\"sel\"]', E('يحوّل الشرائح التي حددتها فقط.', 'Converts only the slides you selected.')],\n      ['#scope [data-v=\"all\"]', E('يحوّل كل شرائح الملف.', 'Converts every slide in the file.')],\n      ['#darkBtn', E('يحوّل الشرائح إلى الوضع الداكن: شريحة لكل جزء بين فاصلين، بخلفية داكنة ونص أبيض. يعمل بعد إكمال الخطوتين 1 و2.', 'Converts the slides to dark mode: one slide per part between separators, dark background and white text. Works after steps 1 and 2.', 'تحويل', 'Convert')],\n      ['#setTog', E('ألوان الخلفية والنص وخيار الصور المستخدمة في التحويل.', 'The background, text and image options used when converting.', 'الإعدادات', 'Settings')],\n      ['.colorbtn[data-k=\"bg\"]', E('لون خلفية الشرائح الداكنة.', 'Background colour of the dark slides.', 'لون الخلفية', 'Background colour')],\n      ['.colorbtn[data-k=\"text\"]', E('لون النص بعد التحويل.', 'Text colour after converting.', 'لون النص', 'Text colour')],\n      ['.colorbtn[data-k=\"accent\"]', E('اللون الذي يحل محل الأزرق في الشرائح الداكنة.', 'The colour that replaces blue on the dark slides.', 'الأزرق يصير', 'Blue becomes')],\n      ['label:has(#imgChk)', E('يجعل الصور الكبيرة (الرسوم والأشكال) بيضاء لتظهر على الخلفية الداكنة.', 'Turns large pictures (drawings and shapes) white so they show on the dark background.')],\n      ['#resetBtn', E('يرجع ألوان التحويل وخياراته إلى الإعدادات الأصلية.', 'Puts the colours and options back to the original settings.', 'استعادة الافتراضي', 'Reset')],\n      ['#tType button', E('اختر نوع الفيديو؛ لكل نوع قالب غلاف خاص به.', 'Pick the video type; each type has its own cover template.')],\n      ['#tThumbs button', E('اختر شكل الغلاف من أشكال هذا النوع.', 'Pick the cover design for this type.', 'شكل الغلاف', 'Cover design')],\n      ['#tTitle', E('اكتب عنوان الفيديو كما يظهر على الغلاف.', 'Type the video title as it should appear on the cover.', 'عنوان الفيديو', 'Video title')],\n      ['#tSub', E('سطر ثانٍ تحت العنوان، ويمكن تركه فارغًا.', 'A second line under the title; it can stay empty.', 'العنوان الثانوي', 'Subtitle')],\n      ['#tPos [data-v=\"start\"]', E('يُدرج شريحة الغلاف بالعنوان المكتوب في بداية الملف مباشرة.', 'Inserts the cover slide with your title at the start of the file right away.', 'بداية الملف', 'Start of file')],\n      ['#tPos [data-v=\"before\"]', E('يُدرج شريحة الغلاف قبل الشريحة المحددة. حدّد شريحة أولًا.', 'Inserts the cover slide before the selected slide. Select a slide first.', 'قبل المحددة', 'Before selected')],\n      ['#tPos [data-v=\"after\"]', E('يُدرج شريحة الغلاف بعد الشريحة المحددة. حدّد شريحة أولًا.', 'Inserts the cover slide after the selected slide. Select a slide first.', 'بعد المحددة', 'After selected')],\n      ['#iThumbs button', E('اختر نمط الشريحة الداخلية من الأنماط الثلاثة في قالب الفيديو.', 'Pick one of the three inner slide styles of the video template.', 'نمط الشريحة', 'Slide style')],\n      ['label:has(#iHead)', E('تُدرج الشريحة بمكان للرأس أعلاها (عنوان قصير) فوق مكان المحتوى.', 'The slide gets a header area at the top (a short heading) above the content.', 'مع رأس', 'With a header')],\n      ['#iPos [data-v=\"end\"]', E('يُدرج شريحة داخلية بالنمط المختار في نهاية الملف مباشرة.', 'Inserts an inner slide in the chosen style at the end of the file right away.', 'نهاية الملف', 'End of file')],\n      ['#iPos [data-v=\"before\"]', E('يُدرج شريحة داخلية قبل الشريحة المحددة. حدّد شريحة أولًا.', 'Inserts an inner slide before the selected slide. Select a slide first.', 'قبل المحددة', 'Before selected')],\n      ['#iPos [data-v=\"after\"]', E('يُدرج شريحة داخلية بعد الشريحة المحددة. حدّد شريحة أولًا.', 'Inserts an inner slide after the selected slide. Select a slide first.', 'بعد المحددة', 'After selected')],\n    ],\n\n    restyle: [\n      ['#menuBtn', E('التحقق من التحديثات، وتغيير اللغة، وحول الأداة.', 'Check for updates, change the language and about.')],\n      ['#tabs [data-tab=\"obj\"]', E('تحويل الشريحة كاملة، وتحويل المحدد إلى نوع معيّن أو إضافة جديد إذا لم يكن شيء محددًا، وتنسيق المسافات.', 'Restyle the whole slide; turn the selection into a type, or add a new one when nothing is selected; fix the spacing.')],\n      ['#tabs [data-tab=\"ins\"]', E('أدوات: إدراج ملف وورد مميَّز، وأرقام الصفحات.', 'Tools: insert a tagged Word file, and page numbers.')],\n      ['#tabs [data-tab=\"set\"]', E('إخفاء الحلول وإظهارها لعمل نسخة الطالب، وتمييز ما هو حل وما هو من السؤال.', 'Hide and show the solutions for the student copy, and mark what is a solution and what belongs to the question.')],\n      ['#wtabs [data-tab=\"wtag\"]', E('حدّد المحتوى في الوورد واختر نوعه (سؤال، حل، تعريف…) ليُنقل إلى الباوربوينت.', 'Select content in Word and pick its type (question, solution, definition…) to move it to PowerPoint.')],\n      ['#wtabs [data-tab=\"wrev\"]', E('قائمة الأجزاء المميزة في الملف، وتنبيه للأجزاء غير المميزة.', 'The tagged parts of the file, and a warning about untagged parts.')],\n      ['.scopeSeg [data-v=\"cur\"]', E('تُطبَّق الأوامر على الشريحة الحالية فقط.', 'Commands apply to the current slide only.')],\n      ['.scopeSeg [data-v=\"all\"]', E('تُطبَّق الأوامر على كل شرائح الملف.', 'Commands apply to every slide in the file.')],\n      ['#goBtn', E('يحوّل الشريحة إلى ستايل مذكرة علا: خط UULA Sans والأحجام والألوان، وترتيب المربعات على شبكة الصفحة. إذا طالت الشريحة يسألك قبل تقسيمها.', 'Restyles the slide to the UULA booklet: UULA Sans font, sizes, colours and boxes placed on the page grid. A slide that gets too long is split only if you agree.', 'تحويل', 'Convert')],\n      ['#roles .tbtn, #solRoles .tbtn', function (el) { var n = el.textContent.trim(), own = el.getAttribute('title') || el.dataset.tip; if (own && own !== n) return E(own, own); return E('حدّد مربعًا في الشريحة ثم اضغط ليأخذ ستايل «' + n + '» من المذكرة.', 'Select a box on the slide, then click to give it the \"' + n + '\" booklet style.', n); }],\n      ['#spV', E('يضبط المسافات بين المربعات من الأعلى والأسفل حسب شبكة الصفحة، بدون تداخل أو فراغات زائدة.', 'Fixes the gaps between boxes from top to bottom on the page grid, with no overlaps or extra space.', 'رأسي', 'Vertical')],\n      ['#spH', E('يحاذي المربعات أفقيًا حسب اختيار «المحاذاة الأفقية» تحته: تلقائي أو يمين أو يسار.', 'Aligns the boxes horizontally as set in «Alignment» below: auto, right or left.', 'أفقي', 'Horizontal')],\n      ['#spD', E('يوزّع المربعات على ارتفاع الشريحة كاملة، فتصير المساحة الفارغة تحت الأسئلة ليكتب الطالب. يعمل فقط إذا كانت في الشريحة مساحة فارغة.', 'Spreads the boxes over the full height of the slide, so the empty space goes under the questions for the student to write. Works only if the slide has free space.', 'توزيع', 'Distribute')],\n      ['#hAlign [data-v=\"auto\"]', E('تختار الأداة المحاذاة المناسبة لكل مربع.', 'The tool picks the right alignment for each box.')],\n      ['#hAlign [data-v=\"right\"]', E('تُحاذى المربعات إلى اليمين.', 'Boxes are aligned to the right.')],\n      ['#hAlign [data-v=\"left\"]', E('تُحاذى المربعات إلى اليسار.', 'Boxes are aligned to the left.')],\n      ['#docxBtn', E('اختر ملف وورد ميّزت أجزاءه بالأداة في الوورد؛ كل جزء مميَّز يصبح مربعًا مستقلًا بستايل علا.', 'Pick a Word file whose parts you tagged with the tool in Word; each tagged part becomes its own UULA box.', 'إدراج ملف وورد', 'Insert a Word file')],\n      ['#tpls .tbtn[data-id=\"grid\"]', E('شبكة علا البيانية الفارغة. إذا حددت صورة أو أكثر قبل الضغط، توضع الشبكة مكان كل صورة وبنفس مقاسها؛ وإلا تُضاف تحت آخر عنصر.', 'The empty UULA graph grid. With one or more pictures selected first, the grid takes each picture\\'s place and size; otherwise it is added under the last object.', 'شبكة بيانية', 'Graph grid')],\n      ['#tpls .tbtn', function (el) { var n = el.textContent.trim(); return E('يُدرج «' + n + '» جاهزًا بستايل علا تحت آخر عنصر في الشريحة الحالية.', 'Inserts a ready \"' + n + '\" in UULA style under the last object on the current slide.', n); }],\n      ['#solBtn', E('يخفي الحلول (النص الأزرق والرسومات التي هي حل) أو يظهرها، لعمل نسخة للطالب بدون إجابات. يتغير الزر حسب الشريحة المعروضة: «إظهار الحلول» إذا كانت حلولها مخفية.', 'Hides or shows the solutions (blue text and drawings that are answers), to make a student copy without answers. The button follows the slide on screen: «Show solutions» when its solutions are hidden.')],\n      ['#undoBtn', E('تراجع: يلغي آخر تمييز بأزرار الحلول، فيرجع الاسم واللون والمكان كما كانت. يمكن الضغط أكثر من مرة.', 'Undo: cancels the last mark made with the solution buttons; name, colour and place go back. Press again for earlier marks.', 'تراجع', 'Undo')],\n      ['#redoBtn', E('تقدّم: يعيد التمييز الذي تراجعت عنه.', 'Redo: does again the mark you undid.', 'تقدّم', 'Redo')],\n      ['#solLines [data-v=\"0\"]', E('عند إخفاء الحل يبقى مكانه فارغًا بدون سطور.', 'When a solution is hidden, its place stays empty with no lines.')],\n      ['#solLines [data-v=\"1\"]', E('كل سطر من الحل يختفي ينزل مكانه سطر رمادي فارغ ليكتب الطالب عليه. تختفي السطور عند إظهار الحلول.', 'Every hidden solution line gets an empty grey line for the student to write on. They go away when solutions are shown.')],\n      ['label:has(#numChk)', E('عند تفعيله يُضاف رقم الصفحة أسفل الشرائح تلقائيًا بعد كل تحويل.', 'When on, the page number is added at the bottom of the slides after each conversion.', 'ترقيم الصفحات بعد كل تحويل', 'Number after each conversion')],\n      ['#numStart', E('رقم الشريحة التي يبدأ منها الترقيم.', 'The slide where numbering starts.', 'بداية الترقيم', 'Numbering start')],\n      ['#numHere', E('يجعل الترقيم يبدأ من الشريحة المحددة الآن.', 'Makes numbering start at the slide selected now.', 'الحالية', 'Current')],\n      ['#numAll', E('يعيد ترقيم كل الصفحات الآن.', 'Renumbers all pages now.', 'تحديث أرقام الصفحات', 'Update page numbers')],\n      ['#numDel', E('يحذف أرقام الصفحات الموجودة الآن في كل الشرائح (أرقام الأداة وأرقام الباوربوينت والأرقام المكتوبة أسفل الصفحة)، ويوقف الترقيم التلقائي.', 'Deletes the page numbers now on every slide (the tool\\'s, PowerPoint\\'s and numbers typed at the bottom of the page) and turns automatic numbering off.', 'حذف أرقام الصفحات', 'Delete page numbers')],\n      ['#wroles .tbtn', function (el) { var n = el.textContent.trim(); return E('حدّد المحتوى في الوورد أو ضع المؤشر داخله، ثم اضغط ليُميَّز «' + n + '» بإطار ملوّن.', 'Select content in Word or put the cursor in it, then click to tag it as \"' + n + '\" with a coloured frame.', n); }],\n      ['#wAuto', E('يميّز كل المحتوى غير المميز تلقائيًا حسب كلماته وألوانه. راجع النتيجة بعده.', 'Tags all untagged content automatically by its words and colours. Review the result afterwards.', 'تمييز تلقائي', 'Auto-tag')],\n      ['#wUntag', E('يزيل التمييز عن المحتوى المحدد، ويبقى النص كما هو.', 'Removes the tag from the selected content; the text stays.', 'إزالة التمييز', 'Remove tag')],\n      ['#wRefresh', E('يحدّث قائمة الأجزاء المميزة.', 'Refreshes the list of tagged parts.', 'تحديث', 'Refresh')],\n      ['#wMark', E('يلوّن الأجزاء غير المميزة في الوورد لتجدها بسهولة.', 'Colours the untagged parts in Word so you can find them.', 'لوّن غير المميز', 'Colour untagged')],\n      ['#wUnmark', E('يزيل تلوين الأجزاء غير المميزة.', 'Removes the colouring from untagged parts.', 'إزالة التلوين', 'Remove colouring')],\n      ['#wClear', E('يزيل كل التمييز من الملف، ويبقى النص.', 'Removes every tag from the file; the text stays.', 'إزالة كل التمييز', 'Remove all tags')]\n    ],\n\n    math: [\n      ['#menuBtn', E('جديد، والتعليمات، والاختصارات، والتحقق من التحديثات.', '')],\n      ['#editTools', E('اختر الأدوات التي تظهر في الشريط ورتّبها.', '', 'تخصيص الأدوات')],\n      ['#resetTools', E('يرجع شريط الأدوات إلى وضعه الأصلي.', '', 'الافتراضي')],\n      ['#editSyms', E('اختر الرموز التي تظهر في لوحة الرموز ورتّبها.', '', 'تخصيص الرموز')],\n      ['#resetSyms', E('يرجع لوحة الرموز إلى وضعها الأصلي.', '', 'الافتراضي')],\n      ['[data-act=\"new\"]', E('يمسح مربع الكتابة لتبدأ معادلة جديدة.', '')],\n      ['[data-act=\"help\"]', E('طريقة كتابة الرموز والكسور والجذور بالكلمات.', '')],\n      ['[data-act=\"keys\"]', E('اختصارات لوحة المفاتيح لكتابة الرموز بسرعة.', '')],\n      ['[data-act=\"news\"]', E('آخر ما أُضيف إلى الأداة.', '')]\n    ],\n\n    graph: [],\n\n    geometry: [\n      ['#menuBtn', E('تعديل الشكل المحدد، والتحقق من التحديثات، وتغيير اللغة، وحول الأداة.', 'Edit the selected shape, check for updates, change the language and about.')],\n      ['#loadSelItem', E('حدّد شكلًا أدرجته من قبل بالأداة، ثم اضغط لتعديله هنا.', 'Select a shape you inserted with the tool, then click to edit it here.')],\n      ['#tabs [data-tab=\"p\"]', E('المثلث والمربع والمستطيل ومتوازي الأضلاع والمعين وشبه المنحرف والمضلعات المنتظمة.', 'Triangles, squares, rectangles, parallelograms, rhombuses, trapezoids and regular polygons.')],\n      ['#tabs [data-tab=\"c\"]', E('الدائرة وعناصرها: المركز ونصف القطر والقطر والوتر والمماس والقوس والقطاع والزوايا.', 'The circle and its parts: center, radius, diameter, chord, tangent, arc, sector and angles.')],\n      ['#tabs [data-tab=\"s\"]', E('المكعب ومتوازي المستطيلات والمنشور والهرم والأسطوانة والمخروط والكرة.', 'Cube, cuboid, prism, pyramid, cylinder, cone and sphere.')],\n      ['#galP button, #galS button', E('اضغط لرسم هذا الشكل.', 'Click to draw this shape.')],\n      ['#segTri button', E('نوع المثلث. السحب يحافظ على النوع.', 'Triangle type. Dragging keeps the type.')],\n      ['#segN button', E('عدد أضلاع المضلع المنتظم.', 'Number of sides of the regular polygon.')],\n      ['#segHid button', E('طريقة رسم الأحرف الخلفية المخفية: متقطعة أو مخفية أو متصلة.', 'How hidden back edges are drawn: dashed, hidden or solid.')],\n      ['#insert', E('في الباوربوينت: يُدرج الشكل أشكالًا عادية في مجموعة واحدة، يمكن تعديلها وتحريكها. في الوورد: صورةً.', 'In PowerPoint: inserts editable shapes in one group. In Word: a picture.', 'إدراج', 'Insert')],\n      ['#undoBtn', E('يتراجع عن آخر تغيير (⌘Z).', 'Undoes the last change (⌘Z).', 'تراجع', 'Undo')],\n      ['#rotBtn', E('يدير الشكل ١٥° عكس عقارب الساعة.', 'Rotates the shape 15° counterclockwise.', 'تدوير', 'Rotate')],\n      ['#flipBtn', E('يعكس الشكل يمينًا ويسارًا.', 'Flips the shape left to right.', 'انعكاس', 'Flip')],\n      ['#resetBtn', E('يرجع الشكل إلى وضعه الأصلي ويمسح العلامات.', 'Returns the shape to its original form and clears the marks.', 'الشكل الأصلي', 'Original shape')],\n      ['#edCancel', E('يلغي تعديل الشكل المحدد، فيُدرج الشكل التالي جديدًا.', 'Stops editing the selected shape; the next insert adds a new one.')],\n      ['#chips .chip', E('يُظهر هذا العنصر على الشكل أو يخفيه.', 'Shows or hides this item on the shape.')],\n      ['#dims input', E('النص المكتوب على هذا البعد في الرسم.', 'The text written on this dimension.')],\n      ['#pop [data-a=\"show\"]', E('يكتب طول الضلع بجانبه. اكتب في المربع نصًا آخر إن أردت.', 'Writes the side length next to it. Type other text in the box if you like.', 'إظهار الطول', 'Show length')],\n      ['#pop [data-a^=\"t\"]', E('شرطات تساوي الأضلاع: الأضلاع المتساوية لها العدد نفسه من الشرطات.', 'Equal-side marks: equal sides get the same number of marks.', 'شرطات التساوي', 'Equal marks')],\n      ['#pop [data-a^=\"p\"]', E('رمز التوازي المعتمد //: الأضلاع المتوازية لها الرمز نفسه.', 'The parallel sign //: parallel sides get the same sign.', 'رمز التوازي', 'Parallel sign')],\n      ['#pop [data-a=\"dash\"]', E('يرسم هذا الضلع بخط متقطع.', 'Draws this side dashed.', 'متقطع', 'Dashed')],\n      ['#pop [data-a=\"nm\"]', E('يُظهر اسم الرأس أو يخفيه. غيّر الاسم من المربع.', 'Shows or hides the vertex name. Change the name in the box.', 'اسم الرأس', 'Vertex name')],\n      ['#pop [data-a=\"sa\"]', E('يكتب قياس الزاوية. اكتب في المربع قياسًا آخر أو رمزًا إن أردت.', 'Writes the angle measure. Type another value or symbol in the box if you like.', 'قياس الزاوية', 'Angle measure')],\n      ['#pop [data-a=\"rt\"]', E('علامة الزاوية القائمة عند هذا الرأس.', 'Right-angle mark at this vertex.', 'زاوية قائمة', 'Right angle')],\n      ['#pop [data-a^=\"a\"]', E('أقواس تساوي الزوايا: الزوايا المتساوية لها العدد نفسه من الأقواس.', 'Equal-angle arcs: equal angles get the same number of arcs.', 'أقواس التساوي', 'Equal arcs')],\n      ['#pop [data-a=\"alt\"]', E('الارتفاع من هذا الرأس، مع علامة القائمة عند قدمه.', 'The altitude from this vertex, with a right-angle mark at its foot.', 'الارتفاع', 'Altitude')],\n      ['#pop [data-a=\"med\"]', E('المتوسط من هذا الرأس إلى منتصف الضلع المقابل.', 'The median from this vertex to the midpoint of the opposite side.', 'المتوسط', 'Median')],\n      ['#pop [data-a=\"bis\"]', E('منصف الزاوية عند هذا الرأس.', 'The angle bisector at this vertex.', 'منصف الزاوية', 'Bisector')],\n      ['#cLine', E('لون خطوط الشكل.', 'Color of the shape\\'s lines.', 'لون الخط', 'Line color')],\n      ['#wSel', E('سماكة خطوط الشكل بالنقاط.', 'Line width in points.', 'سماكة الخط', 'Line width')],\n      ['#dSolid', E('خطوط الشكل متصلة.', 'Solid lines.', 'خط متصل', 'Solid line')],\n      ['#dDash', E('خطوط الشكل متقطعة.', 'Dashed lines.', 'خط متقطع', 'Dashed line')],\n      ['#cFill', E('لون تعبئة الشكل، أو بلا لون.', 'Fill color of the shape, or none.', 'التعبئة', 'Fill')],\n      ['#cText', E('لون أسماء الرؤوس والأطوال والقياسات.', 'Color of names, lengths and measures.', 'لون الكتابة', 'Text color')],\n      ['#cMark', E('لون علامات التساوي والتوازي والزوايا.', 'Color of equal, parallel and angle marks.', 'لون العلامات', 'Marks color')],\n      ['#fsSel', E('حجم الكتابة على الشكل بخط المذكرة.', 'Text size on the shape, in the booklet font.', 'حجم الكتابة', 'Text size')]\n    ]\n  };\n  RULES.cover = RULES.dark;\n\n  // ---------- explanations found by the button's own name (Arabic Math, UULA Graph) ----------\n  var LABELS = {\n    math: {\n      'نسخ النص': E('ينسخ نص المعادلة المكتوب في مربع الكتابة لتلصقه في مكان آخر.'),\n      'قص': E('يقص النص المحدد في مربع الكتابة.'),\n      'لصق': E('يلصق نصًا منسوخًا في مربع الكتابة.'),\n      'مسح الكل': E('يمسح مربع الكتابة لتبدأ معادلة جديدة.'),\n      'السابقة': E('المعادلات التي كتبتها من قبل؛ اختر واحدة لإرجاعها إلى مربع الكتابة.'),\n      'تراجع (⌘Z)': E('يتراجع عن آخر تعديل في الكتابة.'),\n      'إعادة (⌘⇧Z)': E('يعيد التعديل الذي تراجعت عنه.